void SPRITESHEET_desenharSprite(SpritesheetIdx index, uint16_t x, uint16_t y){
    uint16_t *spr;
    switch (index) {
        case PLAYER:
        spr = playerSprite;
        break;
        case ZUMBI:
        spr = zumbiSprite;
        break;
    }
    LCD_desenharSprite(spr,x,y,TAMANHO_SPRITE);
}
